  `driver_id` bigint NOT NULL,
  `route_id` bigint NOT NULL,
  `vehicle_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  KEY `FKssu3f8f38scbwus9jagc78g0i` (`driver_id`),
  KEY `FK8dm8bjrlx14u4vqiogklo8gdr` (`route_id`),
  KEY `FKqymq2msbu3hff93okm3co45nt` (`vehicle_id`),
  CONSTRAINT `FK8dm8bjrlx14u4vqiogklo8gdr` FOREIGN KEY (`route_id`) REFERENCES `route` (`id`),
  CONSTRAINT `FKqymq2msbu3hff93okm3co45nt` FOREIGN KEY (`vehicle_id`) REFERENCES `vehicle` (`id`),
